  r.integration_id AS r_integration_id,
  r.id_sdm AS r_id_sdm,
  r.parent_id AS r_parent_id,
  r.scope_key AS r_scope_key,
  r.item_key AS r_item_key,
  r.fetched_at AS r_fetched_at,
  r.changed_at AS r_changed_at,
  replica.try_uuid(r.payload_json->>'id') AS "id",
  nullif(r.payload_json->>'nama', '') AS "nama",
  nullif(r.payload_json->>'tautan', '') AS "tautan",
  nullif(r.payload_json->>'nama_file', '') AS "nama_file",
  nullif(r.payload_json->>'jenis_file', '') AS "jenis_file",
  nullif(r.payload_json->>'keterangan', '') AS "keterangan",
  nullif(r.payload_json->>'jenis_dokumen', '') AS "jenis_dokumen",
  replica.try_timestamp(r.payload_json->>'tanggal_upload') AS "tanggal_upload",
  replica.try_bigint(r.payload_json->>'id_jenis_dokumen') AS "id_jenis_dokumen",
  r.payload_json AS r_payload
FROM public.sister_replica_record r
WHERE r.endpoint = '/dokumen/{id}' AND r.deleted_at IS NULL;
COMMENT ON VIEW replica."dokumen" IS 'SISTER /dokumen/{id} (generated)';

