  replica.try_bigint(r.payload_json->>'masa_kerja_bulan') AS "masa_kerja_bulan",
  replica.try_bigint(r.payload_json->>'masa_kerja_tahun') AS "masa_kerja_tahun",
  nullif(r.payload_json->>'pangkat_golongan', '') AS "pangkat_golongan",
  replica.try_bigint(r.payload_json->>'id_pangkat_golongan') AS "id_pangkat_golongan",
