CREATE VIEW replica."riwayat_pekerjaan_dokumen" AS
SELECT
  r.integration_id AS r_integration_id,
  r.id_sdm AS r_id_sdm,
  CASE WHEN r.item_key = 'self' THEN coalesce(r.parent_id, r.id_sdm) ELSE r.item_key END AS r_parent_id,
  r.scope_key AS r_scope_key,
  e.ordinality AS r_item_key,
  r.fetched_at AS r_fetched_at,
  r.changed_at AS r_changed_at,
  replica.try_uuid(e.value->>'id') AS "id",
  nullif(e.value->>'nama', '') AS "nama",
  nullif(e.value->>'tautan', '') AS "tautan",
  nullif(e.value->>'nama_file', '') AS "nama_file",
  nullif(e.value->>'jenis_file', '') AS "jenis_file",
  nullif(e.value->>'keterangan', '') AS "keterangan",
  nullif(e.value->>'jenis_dokumen', '') AS "jenis_dokumen",
  replica.try_timestamp(e.value->>'tanggal_upload') AS "tanggal_upload",
  e.value AS r_payload
FROM public.sister_replica_record r
CROSS JOIN LATERAL jsonb_array_elements(
  CASE WHEN jsonb_typeof(r.payload_json->'dokumen') = 'array'
    THEN r.payload_json->'dokumen' ELSE '[]'::jsonb END
) WITH ORDINALITY AS e(value, ordinality)
WHERE r.endpoint = '/riwayat_pekerjaan/{id}' AND r.deleted_at IS NULL AND jsonb_typeof(e.value) = 'object';
COMMENT ON VIEW replica."riwayat_pekerjaan_dokumen" IS 'SISTER /riwayat_pekerjaan/{id} -> dokumen[] (generated)';

